@st.cache_data
def load_data():
    routes = pd.read_csv("Dataset/ML Intern Dataset.csv")
    trains = pd.read_csv("Dataset/ML_Train_Level_Data.csv")

    routes["Station_Name"] = routes["Station_Name"].astype(str).str.strip()
    routes = routes.sort_values(["Train_No", "SN"]).reset_index(drop=True)

    return routes, trains


route_df, ml_df = load_data()


