# MODEL
# ============================================================

X = ml_df[["Total_Distance", "Number_of_Stops"]]
y = ml_df["Journey_Duration_Minutes"]

X_train, X_test, y_train, y_test = train_test_split(
    X, y, test_size=0.20, random_state=42
)

model = LinearRegression()
model.fit(X_train, y_train)
y_pred = model.predict(X_test)

mae = mean_absolute_error(y_test, y_pred)
rmse = np.sqrt(mean_squared_error(y_test, y_pred))
r2 = r2_score(y_test, y_pred)

X_basic = ml_df[["Total_Distance"]]
Xb_train, Xb_test, yb_train, yb_test = train_test_split(
    X_basic, y, test_size=0.20, random_state=42
)

basic_model = LinearRegression()
basic_model.fit(Xb_train, yb_train)
basic_pred = basic_model.predict(Xb_test)

basic_mae = mean_absolute_error(yb_test, basic_pred)
basic_rmse = np.sqrt(mean_squared_error(yb_test, basic_pred))


